{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Practical coaching for energy, habits, and sustainable wellbeing in {{CITY}}, {{STATE}}. Join a VIP Day or weekly pathway to create reliable routines." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="site">
  <header class="nav-outer">
    <div class="container nav">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" id="mainNav">
        <a href="about.html">About</a>
        <a href="programs.html">Paths</a>
        <a href="services.html">Services</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div class="nav-actions">
        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <button class="burger" id="burger" aria-label="Menu">☰</button>
      </div>
    </div>
  </header>

  <main>
    <!-- Hero: gallery style, strong visual -->
    <section class="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <h1>Calm momentum for everyday wellbeing</h1>
          <p class="lede">I help busy people build small, science-informed habits that add up to reliable energy, clearer focus, and kinder routines—without burnout.</p>
          <p class="byline">With {{COACH_NAME}}, {{CREDENTIALS}} — serving {{CITY}}, {{STATE}} and online.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="#lead-magnet">Get the One-Week Reset</a>
          </div>
          <ul class="trust-inline">
            <li>30-minute clarity call</li>
            <li>Evidence-informed frameworks</li>
            <li>Flexible online scheduling</li>
          </ul>
        </div>
        <div class="hero-visual">
          <img src="assets/img/hero.svg" alt="Illustration of calm habits gallery" />
          <div class="avatar">
            <img src="assets/img/avatar.svg" alt="{{COACH_NAME}} avatar" />
            <div class="avatar-text">{{COACH_NAME}} • {{CREDENTIALS}}</div>
          </div>
        </div>
      </div>
    </section>

    <!-- Social proof: short testimonial bar -->
    <section class="social-proof">
      <div class="container">
        <h2>Stories of steady change</h2>
        <div class="testimonials">
          <blockquote>"I sleep better and wake up with a plan—not a to-do pile." <cite>— A client in {{CITY}}</cite></blockquote>
          <blockquote>"The VIP Day transformed my approach to habits — fast and sustainable." <cite>— L. R.</cite></blockquote>
          <blockquote>"Gentle accountability that actually works." <cite>— S. M.</cite></blockquote>
        </div>
      </div>
    </section>

    <!-- Benefits: outcomes focused -->
    <section class="benefits">
      <div class="container">
        <h2>What people gain</h2>
        <div class="cards">
          <article class="card">
            <h3>Consistent energy</h3>
            <p>Practical routines for mornings and midday resets that protect your concentration and mood.</p>
          </article>
          <article class="card">
            <h3>Simpler choices</h3>
            <p>Replace decision fatigue with tiny defaults so each day feels less chaotic.</p>
          </article>
          <article class="card">
            <h3>Skills you keep</h3>
            <p>Coaching that focuses on habits and accountability, not quick fixes—so gains stick.</p>
          </article>
        </div>
      </div>
    </section>

    <!-- Process: how it works -->
    <section class="process">
      <div class="container">
        <h2>How we work together</h2>
        <ol class="steps">
          <li><strong>Clarity call:</strong> 30 minutes to map your priorities and pick an initial pathway.</li>
          <li><strong>VIP Day or Path:</strong> In-depth day-long planning (VIP Day) or weekly coaching pathways to implement systems.</li>
          <li><strong>Measure & refine:</strong> Small experiments, short commitments, clear signals to keep progress reliable.</li>
        </ol>
        <p class="note">I offer a VIP Day for rapid resets and multi-week paths for gradual, sustained change.</p>
      </div>
    </section>

    <!-- Lead magnet: simple form -->
    <section id="lead-magnet" class="lead-magnet">
      <div class="container">
        <div class="magnet-grid">
          <div class="magnet-copy">
            <h2>Free: One-Week Reset Guide</h2>
            <p>Download a gentle, day-by-day plan to regain clarity and restore your rhythm. Includes quick habit templates and reflection prompts.</p>
            <form id="magnetForm" class="magnet-form">
              <label for="email">Email</label>
              <input id="email" name="email" type="email" placeholder="you@domain.com" required />
              <button type="submit" class="btn primary">Send the Guide</button>
              <p class="form-note">We respect your privacy. No spam, ever.</p>
            </form>
          </div>
          <div class="magnet-visual">
            <img src="assets/img/pattern.svg" alt="Decorative pattern" />
          </div>
        </div>
      </div>
    </section>

    <!-- FAQ: top concerns -->
    <section class="faq">
      <div class="container">
        <h2>Common questions</h2>
        <details>
          <summary>How is a VIP Day different from a multi-week program?</summary>
          <p>A VIP Day is an intensive planning and habit-design session to set systems quickly; multi-week programs focus on gradual implementation and weekly accountability.</p>
        </details>
        <details>
          <summary>Do you offer sliding scale or package discounts?</summary>
          <p>Some options and seasonal discounts are available—contact {{EMAIL}} to discuss what might work for your budget.</p>
        </details>
        <details>
          <summary>Will I get worksheets and tools?</summary>
          <p>Yes—each pathway includes practical templates, tracking prompts, and lightweight reflection tools you can reuse.</p>
        </details>
      </div>
    </section>

    <!-- Call to action: clear next step -->
    <section class="cta-strip">
      <div class="container cta-inner">
        <div>
          <h3>Ready to create steady momentum?</h3>
          <p>Start with a clarity call or book a VIP Day for a focused, tangible reset.</p>
        </div>
        <div class="cta-actions">
          <a class="btn ghost" href="book.html">Book a clarity call</a>
          <a class="btn primary" href="pricing.html">See investment</a>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
        <p><a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
      <nav>
        <a href="about.html">About</a>
        <a href="programs.html">Paths</a>
        <a href="services.html">Services</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div class="small-print">© <span id="year"></span> {{BUSINESS_NAME}}. All rights reserved.</div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
