{"path":"assets/css/styles.css","content":"/* Lux gallery — premium, gallery-like layout */
:root{
  --bg:#fbfaf9;--muted:#6b6b6b;--accent:#5b7cfa;--accent-2:#7ac7b9;--card:#ffffff;--radius:12px;
  --max:1100px;--container-padding:24px;--font-sans:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:var(--font-sans);color:#111;background:var(--bg);}
.container{max-width:var(--max);margin:0 auto;padding:0 var(--container-padding)}
.nav-outer{backdrop-filter:blur(6px);background:linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0.35));border-bottom:1px solid rgba(16,24,40,0.04)}
.nav{display:flex;align-items:center;justify-content:space-between;padding:18px 0}
.brand{font-weight:700;color:#0b1020;text-decoration:none;font-size:1.05rem}
.main-nav{display:flex;gap:18px}
.main-nav a{color:var(--muted);text-decoration:none;font-size:0.95rem}
.nav-actions{display:flex;align-items:center;gap:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:white}
.btn.ghost{background:transparent;border:1px solid rgba(11,16,32,0.06);color:#0b1020}
.burger{display:none;background:none;border:none;font-size:1.2rem}

.hero{padding:44px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:center}
.hero-copy h1{font-size:2.05rem;margin:0 0 12px;color:#051129}
.lede{color:var(--muted);margin:0 0 12px}
.byline{font-size:0.92rem;color:var(--muted);margin-bottom:16px}
.hero-ctas{display:flex;gap:10px;margin-bottom:14px}
.trust-inline{list-style:none;padding:0;margin:0;display:flex;gap:10px;color:var(--muted);font-size:0.9rem}
.hero-visual{position:relative}
.hero-visual img{width:100%;height:auto;border-radius:14px;box-shadow:0 8px 30px rgba(11,16,32,0.06);background:#fff}
.avatar{position:absolute;bottom:-22px;left:18px;display:flex;align-items:center;gap:10px;background:linear-gradient(180deg,rgba(255,255,255,0.9),#fff);padding:10px;border-radius:14px;box-shadow:0 6px 22px rgba(11,16,32,0.06)}
.avatar img{width:56px;height:56px;border-radius:50%;background:white}
.avatar-text{font-size:0.9rem}

.social-proof{padding:26px 0 10px}
.social-proof h2{margin:0 0 14px}
.testimonials{display:flex;gap:14px}
.testimonials blockquote{background:var(--card);padding:14px;border-radius:12px;box-shadow:0 6px 18px rgba(11,16,32,0.04);margin:0;font-size:0.95rem}

.benefits{padding:36px 0}
.benefits h2{margin-bottom:18px}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 20px rgba(11,16,32,0.03)}
.card h3{margin:0 0 8px}

.process{padding:30px 0}
.steps{counter-reset:step;list-style:none;padding:0;margin:0}
.steps li{background:linear-gradient(180deg,#fff,#fbfbff);padding:14px;border-radius:10px;margin-bottom:12px;display:flex;gap:12px;align-items:flex-start}
.steps li::before{counter-increment:step;content:counter(step);width:36px;height:36px;border-radius:10px;background:var(--accent);color:white;display:inline-flex;align-items:center;justify-content:center;font-weight:700}
.note{color:var(--muted);margin-top:8px}

.lead-magnet{padding:36px 0}
.magnet-grid{display:grid;grid-template-columns:1fr 320px;gap:20px;align-items:center}
.magnet-form{display:flex;flex-direction:column;gap:8px}
.magnet-form input{padding:12px;border-radius:10px;border:1px solid rgba(11,16,32,0.06)}
.form-note{font-size:0.85rem;color:var(--muted)}
.magnet-visual img{width:100%;border-radius:12px}

.faq{padding:28px 0}
.faq details{background:var(--card);padding:12px;border-radius:10px;margin-bottom:10px}
.faq summary{font-weight:600;cursor:pointer}

.cta-strip{background:linear-gradient(90deg,#f7fbff, #ffffff);padding:20px 0;border-top:1px solid rgba(11,16,32,0.02)}
.cta-inner{display:flex;justify-content:space-between;align-items:center}
.cta-actions{display:flex;gap:10px}

.site-footer{padding:28px 0;border-top:1px solid rgba(11,16,32,0.03);margin-top:36px}
.footer-grid{display:grid;grid-template-columns:1fr 1fr auto;gap:12px;align-items:center}
.footer-grid nav a{display:block;color:var(--muted);text-decoration:none}
.small-print{color:var(--muted);font-size:0.85rem}

/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .magnet-grid{grid-template-columns:1fr}
  .main-nav{display:none}
  .burger{display:inline-block}
  .footer-grid{grid-template-columns:1fr}
  .cards{grid-template-columns:1fr}
  .testimonials{flex-direction:column}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Simple interactions: nav toggle, lead magnet form, year insert, smooth scroll
  var burger = document.getElementById('burger');
  var nav = document.getElementById('mainNav');
  if(burger){
    burger.addEventListener('click', function(){
      if(nav.style.display==='flex') nav.style.display=''; else nav.style.display='flex';
    });
  }

  var yearEl = document.getElementById('year');
  if(yearEl) yearEl.textContent = new Date().getFullYear();

  var form = document.getElementById('magnetForm');
  if(form){
    form.addEventListener('submit', function(e){
      e.preventDefault();
      var email = form.email.value.trim();
      if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){
        alert('Please enter a valid email address');
        return;
      }
      // Simulate simple client-side success
      form.querySelector('button').textContent = 'Sending...';
      setTimeout(function(){
        form.innerHTML = '<p>Thanks — check your inbox for the One-Week Reset. If you do not receive it, email {{EMAIL}}.</p>';
      },800);
    });
  }

  // Anchor smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      var id = a.getAttribute('href');
      var el = document.querySelector(id);
      if(el){
        e.preventDefault();
        el.scrollIntoView({behavior:'smooth',block:'start'});
      }
    });
  });
})();"} 
